const LINE_NAME: Record<string, string> = {
  bogor: "KRL Lin Bogor",
  cikarang: "KRL Lin Cikarang",
  rangkasbitung: "KRL Lin Rangkasbitung",
  priok: "KRL Lin Tanjung Priok",
};

function pad(n: number): string {
  return String(n).padStart(2, "0");
}

/** Menit-absolut WIB -> { "HH:mm", dayOffset }. */
function splitAbs(absMin: number): { time: string; dayOffset: number } {
  const dayOffset = Math.floor(absMin / 1440);
  const wrapped = ((absMin % 1440) + 1440) % 1440;
  return { time: `${pad(Math.floor(wrapped / 60))}:${pad(wrapped % 60)}`, dayOffset };
}

/** Bangun perjalanan KRL nyata dari representasi kompak. */
function buildRealTrips(): Train[] {
  const out: Train[] = [];
  for (const [line, number, pi, startMin, deltas] of RUNS) {
    const codes = PATTERNS[pi].split(" ");
    const absMin: number[] = [startMin];
    for (const d of deltas) absMin.push(absMin[absMin.length - 1] + d);
    const last = codes.length - 1;
    const stops: Stop[] = codes.map((code, i) => {
      const t = splitAbs(absMin[i]);
      const isFirst = i === 0;
      const isLast = i === last;
      return {
        stationCode: code,
        arrive: isFirst ? null : t.time,
        depart: isLast ? null : t.time,
        dayOffset: t.dayOffset,
      };
    });
    const name = LINE_NAME[line] ?? line;
    out.push({
      id: `krl-real-${line}-${number}`,
      number,
      name: `${name} · ${codes[0]} → ${codes[last]}`,
      operator: "KRL",
      serviceClass: "Commuter",
      line,
      stops,
    });
  }
  return out;
}

export const KRL_REAL_TRIPS: Train[] = buildRealTrips();
